    descriptionAdvanced: {
      de: "Das South-Pars-Gasfeld ist das größte Erdgasfeld der Welt und befindet sich im Persischen Golf an der Grenze zwischen Iran und Katar. Es umfasst eine Gesamtfläche von etwa 9.700 Quadratkilometern, von denen 3.700 Quadratkilometer im iranischen Hoheitsgebiet liegen. Dieses geologische Superfeld wurde 1971 entdeckt und enthält schätzungsweise 8 % der weltweiten Gasreserven und 18 % der iranischen Reserven. Die Erschließung des Feldes erfolgt in zahlreichen Phasen, die sowohl die Förderung als auch die Verarbeitung in Onshore-Anlagen in Asaluyeh umfassen. Wirtschaftlich gesehen ist South Pars das Rückgrat der iranischen Energiewirtschaft und versorgt sowohl den Inlandsmarkt als auch die petrochemische Industrie. Die strategische Bedeutung des Feldes wird durch die gemeinsame Nutzung mit Katar verstärkt, das seinen Teil als North Field bezeichnet. Die technologische Komplexität der Offshore-Förderplattformen und der Pipelines unterstreicht die industrielle Kapazität der Region Khuzestan und Bushehr.",
      hu: "A South Pars gázmező a világ legnagyobb földgázmezője, amely a Perzsa-öbölben, Irán és Katar határán található. Teljes területe körülbelül 9700 négyzetkilométer, ebből 3700 négyzetkilométer esik Irán felségvizeire. Ezt a geológiai szupermezőt 1971-ben fedezték fel, és a becslések szerint a világ gázkészleteinek 8%-át, Irán készleteinek pedig 18%-át tartalmazza. A mező kiaknázása számos szakaszban történik, amely magában foglalja a kitermelést és a szárazföldi feldolgozást Asaluyeh ipari övezetében. Gazdasági szempontból a South Pars az iráni energiaipar gerincét alkotja, ellátva a hazai piacot és a vegyipart egyaránt. A mező stratégiai jelentőségét növeli a Katarral való közös használat, ahol a mező folytatását North Fieldnek nevezik. Az offshore kitermelő platformok és a tenger alatti gázvezetékek technológiai összetettsége jól mutatja a régió ipari kapacitásait Bushehr tartományban.",
      ro: "Câmpul de gaze South Pars este cel mai mare zăcământ de gaze naturale din lume, situat în Golful Persic, la granița dintre Iran și Qatar. Acesta acoperă o suprafață totală de aproximativ 9.700 de kilometri pătrați, din care 3.700 de kilometri pătrați se află în apele teritoriale iraniene. Acest super-zăcământ geologic a fost descoperit în 1971 și conține aproximativ 8% din rezervele mondiale de gaze și 18% din rezervele Iranului. Dezvoltarea câmpului are loc în numeroase faze, implicând atât extracția offshore, cât și procesarea onshore în facilitățile din Asaluyeh. Din punct de vedere economic, South Pars reprezintă coloana vertebrală a industriei energetice iraniene, alimentând piața internă și sectorul petrochimic. Importanța strategică este accentuată de exploatarea comună cu Qatar, care își numește porțiunea North Field. Complexitatea tehnologică a platformelor de extracție și a conductelor submarine subliniază capacitatea industrială a regiunii.",
      en: "The South Pars Gas Field is the world's largest natural gas field, located in the Persian Gulf on the border between Iran and Qatar. It covers a total area of approximately 9,700 square kilometers, with 3,700 square kilometers situated within Iranian territorial waters. This geological super-field was discovered in 1971 and is estimated to contain 8% of the world's gas reserves and 18% of Iran's total reserves. Development of the field is organized into numerous phases, involving both offshore extraction and onshore processing at massive facilities in Asaluyeh. Economically, South Pars is the backbone of Iran's energy sector, supplying the domestic market and fueling the nation's petrochemical industry. Its strategic importance is heightened by its shared nature with Qatar, which refers to its portion as the North Field. The technological complexity of its offshore platforms and subsea pipelines underscores the industrial significance of the Bushehr province.",
      es: "El campo de gas de South Pars es un peso pesado geopolítico y económico en el Golfo Pérsico. Descubierto en 1990, este campo submarino gigante representa la mayor reserva de gas natural conocida en el mundo. Se divide estratégicamente entre Irán y Catar. La extracción y el procesamiento del gas son motores cruciales para el suministro energético y los ingresos del estado iraní. Numerosas plataformas, gasoductos submarinos y plantas de procesamiento masivas en la costa, especialmente en Asaluyeh, forman parte de esta vasta infraestructura. Su tamaño lo convierte en un factor indispensable para los precios globales de la energía.",
      pt: "O gigantesco campo de gás de South Pars é um peso pesado geopolítico e económico no Golfo Pérsico. Descoberto em 1990, este campo submarino representa a maior reserva de gás natural conhecida no mundo. É partilhado estrategicamente entre o Irão e o vizinho Catar. A extração e o processamento do gás natural são motores cruciais para o abastecimento de energia e para as receitas do estado iraniano. Numerosas plataformas, gasodutos submarinos e instalações de processamento gigantescas na costa, especialmente em Asaluyeh, fazem parte desta vasta infraestrutura.",
      fr: "L'immense champ de gaz de South Pars est un poids lourd géopolitique et économique dans le golfe Persique. Découvert en 1990, ce champ sous-marin constitue le plus grand gisement de gaz naturel connu au monde. Il est partagé stratégiquement entre l'Iran et le Qatar. L'extraction et le traitement du gaz sont des moteurs essentiels pour l'approvisionnement énergétique et les revenus de l'État iranien. De nombreuses plates-formes, pipelines sous-marins et usines de traitement géantes sur la côte, notamment à Assalouyeh, composent cette infrastructure colossale.",
    },
