      hu: ["A mező iráni szektora becslések szerint 14 billió köbméter gázt tartalmaz.", "A gáz mellett körülbelül 18 milliárd hordó gázkondenzátum is található a lelőhelyen.", "A fúrások mélysége a tengerfenék alatt eléri a 3000 métert.", "Az iráni részt a Pars Oil and Gas Company (POGC) kezeli és fejleszti.", "A kitermelt gázt tenger alatti vezetékeken szállítják az asaluyehi feldolgozókba.", "Bár 1971-ben fedezték fel, a nagyszabású kitermelés csak az 1990-es évek végén indult meg."],
      ro: ["Sectorul iranian al câmpului conține aproximativ 14 trilioane de metri cubi de gaz.", "Pe lângă gaz, zăcământul deține circa 18 miliarde de barili de condensat de gaz.", "Forajele ajung la adâncimi de până la 3.000 de metri sub fundul mării.", "Partea iraniană este gestionată de compania de stat Pars Oil and Gas Company (POGC).", "Gazul este transportat prin conducte submarine către terminalele din Asaluyeh.", "Exploatarea pe scară largă a început abia la sfârșitul anilor 1990, deși a fost descoperit în 1971."],
      en: ["The field holds an estimated 14 trillion cubic meters of gas in the Iranian sector.", "In addition to gas, it contains about 18 billion barrels of gas condensate.", "Drilling operations reach depths of up to 3,000 meters below the seabed.", "The Iranian portion is managed by the Pars Oil and Gas Company (POGC).", "Extracted gas is transported via subsea pipelines to processing plants in Asaluyeh.", "The field was discovered in 1971 but major development phases began in the late 1990s."],
      es: ["El campo de gas fue descubierto en 1990 por la NIOC.", "La superficie total del campo es de unos 9.700 kilómetros cuadrados.", "Unos 3.700 kilómetros cuadrados se encuentran en aguas territoriales iraníes.", "Alberga aproximadamente 14 billones de metros cúbicos de gas natural.", "Se estiman reservas de condensado de gas de más de 18.000 millones de barriles.", "La extracción se divide en decenas de fases de desarrollo complejas.", "El gas obtenido es esencial para la industria nacional y la exportación."],
