      hu: ["Jelentősen hozzájárul az ország acélexport-kapacitásához.", "Több nagy külszíni bányából áll."],
      ro: ["Contribuie masiv la capacitatea de export de oțel.", "Este alcătuită din mai multe cariere deschise mari."],
      en: ["Massively contributes to the steel export capacity.", "Consists of several large open-pit mines."],
      es: ["Contribuye significativamente a la capacidad de exportación de acero.", "Consta de varias minas a cielo abierto de gran tamaño."],
